def shapes(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; comp=set()
                while stack:
                    p=stack.pop()
                    if p in comp: continue
                    comp.add(p)
                    for d in((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+d[0],p[1]+d[1])
                        if 0<=q[0]<H and 0<=q[1]<W and g[q[0]][q[1]]==col and q not in comp: stack.append(q)
                seen|=comp
                out.append((col,comp))
    return out

def norm(comp):
    rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in comp))

def canon(comp):
    n=norm(comp)
    cands=[n]
    for _ in range(3):
        m=max(r for r,c in n),max(c for r,c in n)
        n=tuple(sorted((c,m[1]-r) for r,c in n)); cands.append(n)
    return min(cands)

def transform(g):
    g=[row[:] for row in g]
    ss=shapes(g)
    # map canonical shape -> set of colors of non-1 shapes
    from collections import defaultdict
    byshape=defaultdict(set)
    for col,comp in ss:
        if col!=1: byshape[canon(comp)].add(col)
    for col,comp in ss:
        if col==1:
            k=canon(comp)
            if byshape[k]:
                newc=min(byshape[k])
                for r,c in comp: g[r][c]=newc
    return g

